"""Tables and golden vectors for `panel_core::pytext`: Python 3.13's text semantics.

Run with the panel image's interpreter (Python 3.13, Unicode 15.1), e.g.:

    docker run --rm --network none -v "$PWD:/src:ro" -v "$OUT:/out" --entrypoint python \
        proxy_panel_by_dubr1k-panel:latest -I /src/panel/crates/core/tests/fixtures/generators/gen_pytext.py /out

Writes `/out/tables.rs` (the Unicode tables the Rust code embeds: `str.isspace`, `str.isprintable`,
decimal digits) and `/out/pytext.json` (the vectors the Rust tests replay).
"""
from __future__ import annotations

import ipaddress
import json
import random
import sys
import unicodedata
from pathlib import Path
from urllib.parse import quote, quote_plus, unquote, urlencode, urlsplit

MAX = sys.maxunicode + 1


def is_surrogate(code: int) -> bool:
    return 0xD800 <= code <= 0xDFFF


def ranges(predicate) -> list[tuple[int, int]]:
    out: list[tuple[int, int]] = []
    for code in range(MAX):
        if predicate(code):
            if out and out[-1][1] == code - 1:
                out[-1] = (out[-1][0], code)
            else:
                out.append((code, code))
    return out


def decimal_ranges() -> list[tuple[int, int]]:
    """Runs of ten consecutive decimal digits, each starting at the digit zero."""
    out = []
    code = 0
    while code < MAX:
        if unicodedata.decimal(chr(code), None) == 0:
            length = 1
            while code + length < MAX and unicodedata.decimal(chr(code + length), None) == length:
                length += 1
            out.append((code, code + length - 1))
            code += length
        else:
            assert unicodedata.decimal(chr(code), None) is None, hex(code)
            code += 1
    return out


def rust_ranges(name: str, items: list[tuple[int, int]], doc: str) -> str:
    body = "\n".join(f"    (0x{a:04X}, 0x{b:04X})," for a, b in items)
    return f"/// {doc}\npub(crate) const {name}: &[(u32, u32)] = &[\n{body}\n];\n"


def tables() -> str:
    space = ranges(lambda c: chr(c).isspace())
    nonprintable = ranges(lambda c: not is_surrogate(c) and not chr(c).isprintable())
    return (
        "// @generated by tests/fixtures/generators/gen_pytext.py from Python "
        f"{sys.version.split()[0]} (Unicode {unicodedata.unidata_version}). Do not edit by hand.\n\n"
        + rust_ranges("WHITESPACE", space, "Code points for which `str.isspace()` is true (also `str.split()`/`strip()`).")
        + "\n"
        + rust_ranges("NON_PRINTABLE", nonprintable,
                      "Code points for which `str.isprintable()` is false (surrogates left out: Rust strings hold none).")
        + "\n"
        + rust_ranges("DECIMAL", decimal_ranges(),
                      "Runs of decimal digits (category Nd); a run starts at the digit zero.")
    )


def random_text(rng: random.Random, length: int = 10) -> str:
    out = []
    for _ in range(rng.randint(0, length)):
        pick = rng.random()
        if pick < 0.35:
            code = rng.randint(0x20, 0x7E)
        elif pick < 0.5:
            code = rng.choice([0x09, 0x0A, 0x0B, 0x0C, 0x0D, 0x1C, 0x1D, 0x1E, 0x1F, 0x20, 0x85, 0xA0, 0x1680,
                               0x2000, 0x200A, 0x200B, 0x2028, 0x2029, 0x202F, 0x205F, 0x3000, 0xFEFF, 0x180E])
        elif pick < 0.6:
            code = rng.randint(0, 0x1F)
        elif pick < 0.85:
            code = rng.randint(0x80, 0xFFFF)
        else:
            code = rng.randint(0x10000, 0x10FFFF)
        if is_surrogate(code):
            code = 0xFFFD
        out.append(chr(code))
    return "".join(out)


def nfc_inputs(rng: random.Random) -> list[str]:
    inputs = []
    for code in range(MAX):
        if is_surrogate(code):
            continue
        char = chr(code)
        decomposition = unicodedata.decomposition(char)
        if decomposition and not decomposition.startswith("<"):
            inputs.append(char)
            inputs.append(unicodedata.normalize("NFD", char))
    hangul = [chr(code) for code in range(0xAC00, 0xD7A4)]
    inputs += rng.sample(hangul, 300)
    inputs += [unicodedata.normalize("NFD", text) for text in rng.sample(hangul, 300)]
    inputs += ["\u1100\u1161", "\u1100\u1161\u11a8", "\u1100\u1161\u11a7", "e\u0301\u0327", "e\u0327\u0301",
               "a\u0328\u0301\u0302", "\u0041\u030a\u0301", "\u212b", "\u2126", "\u1e9b\u0323", "\u0344",
               "\u0f73", "\u0915\u093c", "\U0001109a", "\U00011099\U000110ba", "Ж\u0306", "й", "Й",
               "\u0438\u0306", "Этот сервер", "ﬁ", "①", "Ⅸ", "\u00c5\u0328", "abc", "", "\u0300", "\u0300a"]
    marks = [chr(code) for code in range(0x300, 0x370)] + ["\u0591", "\u05b0", "\u0e48", "\u3099", "\u309a"]
    bases = list("aeiouAEIOUnNcCsSzZ") + ["\u3046", "\u304b", "\u30cf", "\u0430", "\u0435", "\u0438"]
    for _ in range(600):
        inputs.append("".join(rng.choice(bases) + "".join(rng.choice(marks) for _ in range(rng.randint(0, 3)))
                              for _ in range(rng.randint(1, 4))))
    inputs += [random_text(rng, 12) for _ in range(300)]
    return inputs


