def ip_facts(text: str):
    """[input, null] for an invalid address, else [input, version, str(address), is_global, is_private,
    is_multicast, is_loopback, is_link_local, is_unspecified, is_reserved]."""
    try:
        address = ipaddress.ip_address(text)
    except ValueError:
        return [text, None]
    return [text, address.version, str(address), address.is_global, address.is_private, address.is_multicast,
            address.is_loopback, address.is_link_local, address.is_unspecified, address.is_reserved]


def random_ips(rng: random.Random) -> list[str]:
    out = []
    for _ in range(200):
        out.append(str(ipaddress.IPv4Address(rng.getrandbits(32))))
    special = ["0.0.0.0/8", "10.0.0.0/8", "100.64.0.0/10", "127.0.0.0/8", "169.254.0.0/16", "172.16.0.0/12",
               "192.0.0.0/24", "192.168.0.0/16", "198.18.0.0/15", "224.0.0.0/4", "240.0.0.0/4"]
    for net in special:
        network = ipaddress.IPv4Network(net)
        for _ in range(8):
            out.append(str(network.network_address + rng.randrange(network.num_addresses)))
        out.append(str(network.network_address - 1) if int(network.network_address) else "0.0.0.0")
        out.append(str(network.broadcast_address + 1) if int(network.broadcast_address) < 2**32 - 1 else "1.0.0.0")
    for _ in range(200):
        value = rng.getrandbits(128)
        if rng.random() < 0.5:
            mask = rng.getrandbits(8)
            hextets = [(value >> (16 * (7 - i))) & 0xFFFF if mask >> i & 1 else 0 for i in range(8)]
            value = 0
            for hextet in hextets:
                value = value << 16 | hextet
        text = str(ipaddress.IPv6Address(value))
        if rng.random() < 0.3:
            text = text.upper()
        if rng.random() < 0.2:
            text = ":".join(f"{(value >> (16 * (7 - i))) & 0xFFFF:04x}" for i in range(8))
        out.append(text)
    v6special = ["::ffff:0:0/96", "64:ff9b:1::/48", "100::/64", "2001::/23", "2001:db8::/32", "2002::/16",
                 "3fff::/20", "fc00::/7", "fe80::/10", "ff00::/8", "fec0::/10", "2001:20::/28", "2001:30::/28"]
    for net in v6special:
        network = ipaddress.IPv6Network(net)
        for _ in range(6):
            out.append(str(network.network_address + rng.randrange(network.num_addresses)))
    return out


