def split_facts(url: str):
    try:
        parts = urlsplit(url)
    except ValueError as exc:
        return {"input": url, "error": str(exc)}
    out = {"input": url, "scheme": parts.scheme, "netloc": parts.netloc, "path": parts.path,
           "query": parts.query, "fragment": parts.fragment, "username": parts.username,
           "password": parts.password, "hostname": parts.hostname}
    try:
        out["port"] = parts.port
    except ValueError as exc:
        out["port_error"] = str(exc)
    return out


