def py_int(text: str):
    try:
        return {"ok": int(text)}
    except ValueError as exc:
        return {"error": str(exc)}


def py_float(text: str):
    try:
        value = float(text)
    except ValueError as exc:
        return {"error": str(exc)}
    return {"ok": repr(value)}


def main(out: Path) -> None:
    rng = random.Random(1025)
    (out / "tables.rs").write_text(tables(), encoding="utf-8")

    texts = ["", " ", "a b", "  a  b  ", "a\tb\nc", "\x1c\x1d\x1e\x1fa\x1fb", "a\x85b\xa0c", "a\u200bb",
             "a\u2028b\u2029c", "a\u3000b\u202fc\u205fd", "a\ufeffb", "a\u180eb", "Этот  сервер ", "🙂 🙂"]
    texts += [random_text(rng, 16) for _ in range(600)]
    whitespace = [chr(code) for code in range(MAX) if not is_surrogate(code) and chr(code).isspace()]
    texts += ["x" + char + "y" for char in whitespace]
    slices = [(None, None), (0, 1), (1, None), (-1, None), (None, -1), (2, 5), (-5, -2), (5, 2), (0, 100),
              (-100, 3), (3, 3), (10, 20)]
    printable_probe = [chr(code) for code in rng.sample(range(MAX), 3000) if not is_surrogate(code)]
    quote_inputs = ["", "abc", "a b", "a+b", "a/b", "a:b@c", "~_.-", "é", "Этот сервер", "🙂", "%", "%41",
                    "\x00\x7f", "!*'();:@&=+$,/?#[]", "a b+c/d", "<>\"{}|\\^`"] + [random_text(rng, 8) for _ in range(300)]
    safes = ["", "/", ":@", "é/", "~", "+ "]
    unquote_inputs = ["", "abc", "%41", "%4", "%", "%%", "%zz", "a%20b", "%E2%82%AC", "%e2%82", "%C3%A9%C3",
                      "%ff", "Этот%20сервер", "%F0%9F%99%82", "%F0%9F%99", "a+b", "%2B", "%u0041", "%41%4",
                      "%C3%28", "%ED%A0%80", "%F4%90%80%80", "é%41", "%E2%82%ACé%E2"]
    pairs_list = [[("series", "host.cpu"), ("range", "1h")], [("a b", "c&d"), ("é", "🙂"), ("x", "")],
                  [("k", "a/b?c=d#e"), ("plus", "+ +")], []]
    reprs = ["", "a", "it's", 'say "hi"', "both ' and \"", "\\", "\n\r\t", "\x00\x1f\x7f", "\x80\x9f\xa0",
             "é", "Ж", "\u2028", "\ufeff", "🙂", "\U000e0001", "\U0010ffff", "\u0378", "a\u0301"] + [
                 random_text(rng, 8) for _ in range(300)]
    lower_inputs = ["TRUE", "True", "ΣΑΣ", "ΑΣ ΑΣ.", "İ", "ẞ", "ǅ", "Ω", "K", "ΣΑΣ\u0308", "Σ"]
    lower_inputs += [chr(code) for code in range(MAX) if not is_surrogate(code) and chr(code).lower() != chr(code)]

    payload = {
        "python": sys.version,
        "unicode": unicodedata.unidata_version,
        # [input, input.split(), input.strip()]
        "split": [[text, text.split(), text.strip()] for text in texts],
        # [input, input.isprintable()]
        "isprintable": [[text, text.isprintable()] for text in texts + printable_probe],
        # [input, NFC, NFKC]
        "nfc": [[text, unicodedata.normalize("NFC", text), unicodedata.normalize("NFKC", text)]
                for text in nfc_inputs(rng)],
        # [input, len(input), [[start, end, input[start:end]], ...]]
        "slice": [[text, len(text), [[start, end, text[start:end]] for start, end in slices]]
                  for text in texts[:120] + ["🙂a🙂b🙂c", "Этот сервер 🙂"]],
        # [input, safe, quote(input, safe), quote_plus(input, safe)]
        "quote": [[text, safe, quote(text, safe=safe), quote_plus(text, safe=safe)]
                  for text in quote_inputs for safe in safes],
        # [input, quote(input)]
        "quote_default": [[text, quote(text)] for text in quote_inputs],
        # [input, unquote(input)]
        "unquote": [[text, unquote(text)] for text in unquote_inputs + quote_inputs],
        # [pairs, urlencode(pairs)]
        "urlencode": [[pairs, urlencode(pairs)] for pairs in pairs_list],
        # see ip_facts()
        "ip": [ip_facts(text) for text in IPS + random_ips(rng)],
        "urlsplit": [split_facts(url) for url in URLS],
        # [input, repr(input)]
        "repr": [[text, repr(text)] for text in reprs],
        # [input, input.lower()]
        "lower": [[text, text.lower()] for text in lower_inputs],
        "int": [dict(input=text, **py_int(text)) for text in NUMBERS],
        "float": [dict(input=text, **py_float(text)) for text in NUMBERS],
    }
    (out / "pytext.json").write_text(json.dumps(payload, ensure_ascii=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main(Path(sys.argv[1]))
